// Entity representing a task in the database
@Entity
@Table(name = "tasks")
public class Task {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private Long userId; // links to authenticated user

    @Column(nullable = false)
    private String title;

    private String description;
    private Boolean completed = false;
    private LocalDateTime createdAt = LocalDateTime.now();
}

@RestController
@RequestMapping("/api/tasks")
public class TaskController {
    private final TaskService taskService;

    @GetMapping
    public List<Task> getUserTasks(@AuthenticationPrincipal Long userId) {
        return taskService.findAllByUser(userId); // only this user's tasks
    }

    @PostMapping
    public Task createTask(@RequestBody TaskRequest request, @AuthenticationPrincipal Long userId) {
        return taskService.createTask(request.title(), request.description(), userId);
    }

    @PutMapping("/{id}")
    public Task updateTask(@PathVariable Long id, @RequestBody TaskRequest request, @AuthenticationPrincipal Long userId) {
        return taskService.updateTask(id, request, userId); // verify ownership
    }

    @DeleteMapping("/{id}")
    public void deleteTask(@PathVariable Long id, @AuthenticationPrincipal Long userId) {
        taskService.deleteTask(id, userId);
    }
}

@Service
public class TaskService {
    private final TaskRepository taskRepository;

    public List<Task> findAllByUser(Long userId) {
        return taskRepository.findByUserIdOrderByCreatedAtDesc(userId);
    }

    public Task createTask(String title, String description, Long userId) {
        var task = new Task();
        task.setUserId(userId);
        task.setTitle(title);
        task.setDescription(description);
        return taskRepository.save(task);
    }

    public Task updateTask(Long id, TaskRequest request, Long userId) {
        var task = taskRepository.findById(id)
            .orElseThrow(() -> new TaskNotFoundException(id));

        if (!task.getUserId().equals(userId)) {
            throw new UnauthorizedException("Not your task"); // ownership check
        }

        task.setTitle(request.title());
        task.setDescription(request.description());
        task.setCompleted(request.completed());
        return taskRepository.save(task);
    }
}

@Repository
interface TaskRepository extends JpaRepository<Task, Long> {
    List<Task> findByUserIdOrderByCreatedAtDesc(Long userId);
}

record TaskRequest(String title, String description, Boolean completed) {}

// PRESENTATION TIER: Handles HTTP requests and responses
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    @PostMapping
    public ResponseEntity<OrderResponse> placeOrder(@RequestBody OrderRequest request) {
        var order = orderService.createOrder(request); // delegates to application tier
        return ResponseEntity.ok(new OrderResponse(order));
    }

    @GetMapping("/{id}")
    public ResponseEntity<OrderResponse> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(order -> ResponseEntity.ok(new OrderResponse(order)))
            .orElse(ResponseEntity.notFound().build());
    }
}

// APPLICATION TIER: Business logic and orchestration
@Service
@Transactional
public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryService inventoryService;
    private final PaymentService paymentService;

    public Order createOrder(OrderRequest request) {
        // Business logic: validate, check inventory, process payment
        if (request.items().isEmpty()) {
            throw new InvalidOrderException("Order must have items");
        }

        inventoryService.reserveItems(request.items()); // orchestrates multiple operations
        var payment = paymentService.processPayment(request.paymentDetails());

        var order = new Order();
        order.setItems(request.items());
        order.setPaymentId(payment.getId());
        order.setStatus(OrderStatus.CONFIRMED);

        return orderRepository.save(order); // delegates to data tier
    }

    public Optional<Order> findById(Long id) {
        return orderRepository.findById(id);
    }
}

// DATA TIER: Database access and persistence
@Repository
interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByStatusAndCreatedAtAfter(OrderStatus status, LocalDateTime after);

    @Query("SELECT o FROM Order o JOIN FETCH o.items WHERE o.userId = :userId")
    List<Order> findByUserIdWithItems(@Param("userId") Long userId);
}

// 1. Configure stateless sessions using Redis
@Configuration
public class SessionConfig {
    @Bean
    public RedisConnectionFactory redisConnectionFactory() {
        return new LettuceConnectionFactory("redis-host", 6379);
    }
}

// application.properties: spring.session.store-type=redis

// 2. Add caching for frequently accessed data
@Service
public class ProductService {
    private final ProductRepository productRepository;

    @Cacheable(value = "products", key = "#id") // cache product lookups in Redis
    public Optional<Product> findById(Long id) {
        return productRepository.findById(id); // only hits DB on cache miss
    }

    @Cacheable(value = "popularProducts", key = "'top10'")
    public List<Product> findTop10Popular() {
        return productRepository.findTop10ByOrderByViewCountDesc(); // cached for 5 minutes
    }

    @CacheEvict(value = "products", key = "#product.id") // invalidate cache on update
    public Product updateProduct(Product product) {
        return productRepository.save(product);
    }
}

// 3. Configure read replicas in application.properties
// spring.datasource.primary.url=jdbc:mysql://primary-db:3306/myapp
// spring.datasource.replica.url=jdbc:mysql://replica-db:3306/myapp

@Service
@Transactional(readOnly = true) // routes reads to replica by default
public class OrderService {
    private final OrderRepository orderRepository;

    public List<Order> findRecentOrders(Long userId) {
        return orderRepository.findByUserIdOrderByCreatedAtDesc(userId); // goes to read replica
    }

    @Transactional // routes writes to primary database
    public Order createOrder(OrderRequest request) {
        var order = new Order();
        order.setUserId(request.userId());
        order.setItems(request.items());
        return orderRepository.save(order); // write goes to primary
    }
}

